const PORTED_RESPONSES: ReadonlyMap<string, PortedResponse> = new Map(RESPONSE_ROWS);

const usedResponses = new Set<string>();

/** The response output the case `key` now produces, when its golden predates the C3 port. */
export const portedResponse = (key: string): PortedResponse | undefined => {
  const ported = PORTED_RESPONSES.get(key);

  if (ported !== undefined) usedResponses.add(key);

  return ported;
};

/** The response entries no case consumed: stale once the fixtures are regenerated or a case is renamed. */
export const unusedResponseAheadEntries = (): string[] =>
  [...PORTED_RESPONSES.keys()].filter((key) => !usedResponses.has(key));

/** An edit of one golden stream chunk (the parsed JSON object), applied in place. */
type ChunkEdit = (chunk: JsonObject) => void;

const dropNullToolCalls: ChunkEdit = (chunk) => {
  const choices = chunk["choices"];

  if (!Array.isArray(choices)) return;

  for (const choice of choices) {
    const delta = (choice as JsonObject)["delta"] as JsonObject | undefined;

    if (delta !== undefined && delta["tool_calls"] === null) delete delta["tool_calls"];
  }
};

const setPath =
  (path: ReadonlyArray<string | number>, value: Json): ChunkEdit =>
  (chunk) => {
    let node: Json = chunk;

    for (const key of path.slice(0, -1))
      node = (node as Record<string | number, Json>)[key] as Json;
    (node as Record<string | number, Json>)[path.at(-1) as string | number] = value;
  };

/** `line` -> edit; `"*"` edits every chunk of the case. */
type CaseChunkEdits = ReadonlyMap<number | "*", ChunkEdit>;

const CHUNK_EDIT_ROWS: ReadonlyArray<readonly [string, CaseChunkEdits]> = [
  ...[
    "stream: reasoning, text, images, tool calls and final usage",
    "stream: [DONE] synthesises the terminal chunk with pending usage",
    "stream: MAX_TOKENS and empty streams",
  ].map((name): readonly [string, CaseChunkEdits] => [
    `openai->antigravity ${name}`,
    new Map([["*", dropNullToolCalls]]),
  ]),
  [
    "openai->gemini stream: two candidates, max tokens, usage-only chunk and data prefix",
    new Map([[2, setPath(["id"], "multi")]]),
  ],
  [
    "openai->gemini stream: reasoning, text, tool calls, image output and final usage",
    new Map([[2, setPath(["choices", 0, "delta", "content"], "Hi there")]]),
  ],
];

const CHUNK_EDITS: ReadonlyMap<string, CaseChunkEdits> = new Map(CHUNK_EDIT_ROWS);

const usedChunkEdits = new Set<string>();

/** The edit the golden chunk of `line` in case `key` needs, if its golden predates the C6 port. */
export const portedChunkEdit = (key: string, line: number): ((chunk: string) => string) => {
  const edits = CHUNK_EDITS.get(key);
  const edit = edits?.get(line) ?? edits?.get("*");

  if (edit === undefined) return (chunk) => chunk;
  usedChunkEdits.add(key);

  return (chunk) => {
    const apply = (text: string): string => {
      const parsed = JSON.parse(text) as JsonObject;
      edit(parsed);

      return JSON.stringify(parsed);
    };

    return chunk.startsWith("data:") ? `data: ${apply(chunk.slice(5).trim())}` : apply(chunk);
  };
};

/**
 * The cases `translator-fixtures-ids.test.ts` runs (generated ids, `needs: ["id-normalization"]`): the shared harness
 * skips them, so each file checks its own share of the edits.
 */
const ID_CASE_EDITS: ReadonlySet<string> = new Set([
  "openai->antigravity stream: reasoning, text, images, tool calls and final usage",
  "openai->gemini stream: reasoning, text, tool calls, image output and final usage",
]);

/** The chunk-edit entries no case consumed in this test file (`ids`: the generated-id cases' share). */
export const unusedChunkEditEntries = (ids: boolean): string[] =>
  [...CHUNK_EDITS.keys()].filter(
    (key) => ID_CASE_EDITS.has(key) === ids && !usedChunkEdits.has(key),
  );
